import React, { useState } from "react";
import Navbar from "../components/Navbar";
import { api } from "../utils/api";
import { motion } from "framer-motion";
import { Link } from "react-router-dom";

export default function Login() {
  const [loading, setLoading] = useState(false);

  const [form, setForm] = useState({
    email: "",
    password: ""
  });

  async function submit(e) {
    e.preventDefault();
    setLoading(true);

    try {
      // ✅ FIXED ROUTE
      const res = await api.post("/api/auth/login", form);

      localStorage.setItem("user_token", res.data.token);
      localStorage.setItem("user_profile", JSON.stringify(res.data.user));

      window.location.href = "/portal";
    } catch (err) {
      alert(err?.response?.data?.message || "Login failed");
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="min-h-screen bg-gradient-to-b from-gray-50 via-white to-gray-50">
      <Navbar />

      <div className="max-w-lg mx-auto px-4 py-12">
        <motion.div
          initial={{ opacity: 0, y: 16 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.55, ease: "easeOut" }}
        >
          <h1 className="text-4xl font-black tracking-tight">User Login</h1>
          <p className="text-gray-600 mt-2 text-lg">
            Login to see your tickets and SOC reply.
          </p>

          <motion.form
            onSubmit={submit}
            initial={{ opacity: 0, y: 16 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.55, delay: 0.05 }}
            className="mt-10 bg-white rounded-3xl shadow p-7 border space-y-5"
          >
            <div>
              <div className="text-sm font-semibold mb-2">Email</div>
              <input
                className="w-full border rounded-2xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-gray-900/10"
                placeholder="Enter your email"
                type="email"
                value={form.email}
                onChange={(e) => setForm({ ...form, email: e.target.value })}
                required
              />
            </div>

            <div>
              <div className="text-sm font-semibold mb-2">Password</div>
              <input
                className="w-full border rounded-2xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-gray-900/10"
                placeholder="Enter your password"
                type="password"
                value={form.password}
                onChange={(e) => setForm({ ...form, password: e.target.value })}
                required
              />
            </div>

            <button
              disabled={loading}
              className="w-full px-6 py-3 rounded-2xl bg-gray-900 text-white font-semibold hover:opacity-95 active:scale-[0.99] transition disabled:opacity-60"
            >
              {loading ? "Logging in..." : "Login"}
            </button>

            <div className="text-sm text-gray-600 text-center">
              New user?{" "}
              <Link to="/signup" className="text-blue-600 underline">
                Create account
              </Link>
            </div>

            <div className="text-xs text-gray-600 text-center">
              🔒 We never ask for OTP, passwords, or remote access.
            </div>
          </motion.form>
        </motion.div>
      </div>
    </div>
  );
}
